/* ---- rshim: running kernels as R runs a .Call body (edgerpy) ----
 * R's error() never returns: inside R it longjmps back to the evaluator.
 * Here Rf_error() formats the message and longjmps back to rshim_run(),
 * which the Python entry points use to call every kernel. Warnings are
 * collected and handed back to the entry point, which reissues them as
 * Python warnings.
 */
#define RSHIM_MSGLEN 8192
#define RSHIM_MAXWARN 8

typedef struct
{
    char error[RSHIM_MSGLEN];                    /* message of the error() that ended the call */
    int nwarn;                                   /* number of warnings stored below */
    char warn[RSHIM_MAXWARN][RSHIM_MSGLEN];      /* first RSHIM_MAXWARN warning() messages */
} rshim_status;

/* Set the R arithmetic constants (R_NaN, NA_REAL, ...) once at module load. */
void rshim_init(void);

/* Run fn(arg) as R would run a .Call body.
 * Returns 0 on normal completion, 1 if fn called error(); status receives
 * the error message and any warnings. Must not be nested. */
int rshim_run(void (*)(void *), void *, rshim_status *);

